-- Title: catalog patch guard custom field type change when values exist
-- Kind: patch
-- Intent: catalog_custom_field_type_change_guard
-- Context: TH-02 / EPIC-03 / US-02 FR-04 BR-05 — chỉ chặn đổi field_type khi đã có product_custom_field_values
-- Touches: _custom_field_to_json, upsert_custom_field
-- Safety: idempotent ; medium
-- Depends on: 20260710005_catalog_patch_inline_normalize_custom_fields_rpcs
-- Promoted from _drafts/catalog_patch_custom_field_type_change_guard.sql
-- Generated by tools/c45_supabase_migrate/bin/promote_drafts.dart

create or replace function catalog._custom_field_to_json(p_field_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = catalog, pg_temp
as $$
  select jsonb_build_object(
    'field_id', cf.id,
    'group_id', cf.group_id,
    'name', cf.name,
    'field_type', cf.field_type,
    'options', coalesce(
      (
        select jsonb_agg(catalog._custom_field_option_to_json(o) order by o.sort_order, o.label)
        from catalog.custom_field_options o
        where o.field_id = cf.id
      ),
      '[]'::jsonb
    ),
    'is_required', cf.is_required,
    'is_searchable', cf.is_searchable,
    'is_filterable', cf.is_filterable,
    'display_on_list', cf.display_on_list,
    'sort_order', cf.sort_order,
    'status', cf.status,
    'has_product_values', exists (
      select 1
      from catalog.product_custom_field_values v
      where v.custom_field_id = cf.id
    )
  )
  from catalog.custom_fields cf
  where cf.id = p_field_id;
$$;

create or replace function catalog.upsert_custom_field(
  p_tenant_id uuid,
  p_group_id uuid,
  p_name text,
  p_field_type text,
  p_field_id uuid default null,
  p_options jsonb default '[]'::jsonb,
  p_is_active boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_name text;
  v_field_id uuid := p_field_id;
  v_status text := case when coalesce(p_is_active, true) then 'active' else 'inactive' end;
  v_duplicate_id uuid;
  v_option jsonb;
  v_option_index int := 0;
  v_current_field_type text;
begin
  perform catalog._assert_custom_fields_permission(p_tenant_id);

  if not exists (
    select 1
    from catalog.custom_field_groups g
    where g.id = p_group_id
      and g.tenant_id = p_tenant_id
  ) then
    raise exception 'custom field group not found';
  end if;

  v_name := catalog._normalize_custom_field_name(p_name);
  if v_name is null then
    raise exception 'validation_exception: Field name must not be empty.';
  end if;

  if coalesce(nullif(btrim(p_field_type), ''), '') not in (
    'text', 'number', 'date', 'boolean', 'singleSelect'
  ) then
    raise exception 'validation_exception: Unsupported field type.';
  end if;

  if p_field_type = 'singleSelect'
     and (
       p_options is null
       or jsonb_array_length(p_options) = 0
     )
     and v_field_id is null then
    raise exception 'validation_exception: Single select field requires options.';
  end if;

  if v_field_id is not null then
    select f.field_type
    into v_current_field_type
    from catalog.custom_fields f
    where f.id = v_field_id
      and f.group_id = p_group_id
      and f.tenant_id = p_tenant_id;

    if v_current_field_type is null then
      raise exception 'custom field not found';
    end if;

    if p_field_type is distinct from v_current_field_type
       and exists (
         select 1
         from catalog.product_custom_field_values v
         where v.custom_field_id = v_field_id
           and v.tenant_id = p_tenant_id
       )
    then
      raise exception 'custom_field_type_change_blocked';
    end if;

    select f.id
    into v_duplicate_id
    from catalog.custom_fields f
    where f.group_id = p_group_id
      and f.name = v_name
      and f.status = 'active'
      and f.id <> v_field_id
    limit 1;

    if v_duplicate_id is not null then
      raise exception 'duplicate custom field name "%"', v_name;
    end if;

    update catalog.custom_fields f
    set
      name = v_name,
      field_type = p_field_type,
      status = v_status,
      updated_at = now()
    where f.id = v_field_id;

    delete from catalog.custom_field_options o
    where o.field_id = v_field_id;
  else
    select f.id
    into v_duplicate_id
    from catalog.custom_fields f
    where f.group_id = p_group_id
      and f.name = v_name
      and f.status = 'active'
    limit 1;

    if v_duplicate_id is not null then
      raise exception 'duplicate custom field name "%"', v_name;
    end if;

    insert into catalog.custom_fields (
      tenant_id,
      group_id,
      name,
      field_type,
      sort_order,
      status
    )
    values (
      p_tenant_id,
      p_group_id,
      v_name,
      p_field_type,
      (
        select coalesce(max(f.sort_order), -1) + 1
        from catalog.custom_fields f
        where f.group_id = p_group_id
      ),
      v_status
    )
    returning id into v_field_id;
  end if;

  if p_field_type = 'singleSelect' and p_options is not null then
    for v_option in
      select value
      from jsonb_array_elements(p_options)
    loop
      insert into catalog.custom_field_options (
        tenant_id,
        field_id,
        label,
        sort_order,
        is_active
      )
      values (
        p_tenant_id,
        v_field_id,
        btrim(v_option ->> 'label'),
        coalesce((v_option ->> 'sort_order')::int, v_option_index),
        coalesce((v_option ->> 'is_active')::boolean, true)
      );
      v_option_index := v_option_index + 1;
    end loop;
  end if;

  return catalog._custom_field_to_json(v_field_id);
end;
$$;
